"""Module registry (generated by api/tools/build_registry.py from the transpiled client).

Used for the per-module Swagger sections and to check statements the client sends:
  SB_ALLOWLIST=off      everything is accepted
  SB_ALLOWLIST=audit    unknown statements are accepted and appended to SB_AUDIT_FILE (default)
  SB_ALLOWLIST=enforce  only registered statements (and those in registry/approved.sql) run

Statements built at run time by string concatenation (filters, sort orders) are not in the registry;
run in audit mode first, review the audit file and copy approved statements to approved.sql.
"""
from __future__ import annotations

import datetime as dt
import json
import re
import threading
from functools import lru_cache
from pathlib import Path

from .config import settings

REG_DIR = Path(__file__).resolve().parent / 'registry'
_audit_lock = threading.Lock()


def norm(sql: str) -> str:
    """Whitespace-insensitive, case-insensitive outside string literals."""
    parts = re.split(r"('(?:[^']|'')*')", sql or '')
    out = []
    for i, p in enumerate(parts):
        out.append(p if i % 2 else ' '.join(p.split()).upper())
    return ' '.join(''.join(out).split()).rstrip(';').strip()


@lru_cache(maxsize=1)
def index() -> list[dict]:
    f = REG_DIR / '_index.json'
    return json.loads(f.read_text(encoding='utf-8')) if f.exists() else []


@lru_cache(maxsize=512)
def module(name: str) -> dict | None:
    f = REG_DIR / f'{name}.json'
    if not f.exists() or name.startswith('_'):
        return None
    return json.loads(f.read_text(encoding='utf-8'))


@lru_cache(maxsize=1)
def _known() -> tuple[frozenset, dict]:
    stmts: set[str] = set()
    sources: dict[str, str] = {}
    names = [m['name'] for m in index()]
    for n in names:
        m = module(n)
        if not m:
            continue
        for d in m['datasets']:
            if d['sql'].strip():
                stmts.add(norm(d['sql']))
            sources.setdefault(d['source'].upper(), n)
        for s in m.get('sql', []):
            stmts.add(norm(s))
        for p in m.get('packages', []):
            sources.setdefault(p['source'].upper(), n)
    approved = REG_DIR / 'approved.sql'
    if approved.exists():
        for block in approved.read_text(encoding='utf-8').split('\n/\n'):
            if block.strip():
                stmts.add(norm(block))
    return frozenset(stmts), sources


def module_of(source: str) -> str | None:
    return _known()[1].get((source or '').upper())


def is_known(sql: str) -> bool:
    n = norm(sql)
    known = _known()[0]
    if n in known:
        return True
    # DOA appends nothing, but the client substitutes &/otSubst variables and the Delphi code often
    # appends WHERE/ORDER BY parts to a registered base statement
    return any(n.startswith(k) for k in known if len(k) > 30 and k.startswith('SELECT'))


def check(sql: str, source: str, user: str) -> None:
    """Raises PermissionError in enforce mode for statements outside the registry."""
    if settings.allowlist == 'off' or is_known(sql):
        return
    if settings.allowlist == 'audit':
        settings.audit_file.parent.mkdir(parents=True, exist_ok=True)
        with _audit_lock, settings.audit_file.open('a', encoding='utf-8') as fh:
            fh.write(f'-- {dt.datetime.now().isoformat(timespec="seconds")} {user} {source}\n{sql.strip()}\n/\n')
        return
    raise PermissionError(f'Statement from {source} is not registered for this application')
